from langchain_core.tools import tool
from langgraph.types import Command

@tool
def transfer_to_billing() -> Command:
    """Hand the conversation to the billing specialist."""
    return Command(goto="billing", graph=Command.PARENT)

from langgraph.config import get_stream_writer

def crawl(state):
    writer = get_stream_writer()
    for i, url in enumerate(state["urls"], 1):
        writer({"progress": f"{i}/{len(state['urls'])}", "url": url})
        fetch(url)
    return {"done": True}

